<section class="page-heading"><div><p class="page-kicker"><?=e($document['display_code'])?></p><h2><?=e($document['document_number'])?></h2><p><?=e($document['type_name'].' — '.$document['site_code'])?></p></div><?php if($document['entity_type']==='weighings'):?><a class="page-action" target="_blank" href="<?=e(base_url('weighings/'.$document['entity_id'].'/ticket?export=pdf'))?>"><i class="bi bi-file-earmark-pdf"></i><span>PDF</span></a><?php elseif($document['entity_type']==='distributions'):?><a class="page-action" target="_blank" href="<?=e(base_url('distributions/'.$document['entity_id'].'/print?export=pdf'))?>"><i class="bi bi-file-earmark-pdf"></i><span>PDF</span></a><?php endif;?></section>
<?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?>
<section class="metric-grid"><article class="metric-card"><span>Statut</span><strong><?=e($document['status'])?></strong></article><article class="metric-card"><span>Exercice</span><strong><?=e($document['period_key'])?></strong></article><article class="metric-card"><span>Créateur</span><strong><?=e($document['creator_name']?:'-')?></strong></article><article class="metric-card"><span>Validateur</span><strong><?=e($document['validator_name']?:'-')?></strong></article></section>
<?php $actions=['draft'=>['submit'=>'Soumettre'],'rejected'=>['submit'=>'Resoumettre'],'submitted'=>['request-approval'=>'Demander approbation'],'pending_approval'=>['approve'=>'Approuver','reject'=>'Refuser'],'approved'=>['start'=>'Démarrer','close'=>'Clôturer'],'in_progress'=>['receive'=>'Réceptionner'],'received'=>['close'=>'Clôturer']]; ?>
<?php if(!empty($actions[$document['workflow_state']])): ?><section class="form-panel"><h3>Actions de validation</h3><div class="table-actions"><?php foreach($actions[$document['workflow_state']] as $action=>$label): ?><form method="post" action="<?=e(base_url('documents/'.$document['id'].'/'.$action))?>" class="enterprise-form"><?=csrf_field()?><?php if($action==='reject'):?><input name="reason" required placeholder="Motif obligatoire"><?php endif;?><button class="btn-primary"><?=e($label)?></button></form><?php endforeach;?></div></section><?php endif; ?>
<section class="form-panel"><h3>Ajouter une pièce jointe</h3><form method="post" enctype="multipart/form-data" action="<?=e(base_url('documents/'.$document['id'].'/attachments'))?>" class="enterprise-form"><?=csrf_field()?><input type="file" name="attachment" accept="application/pdf,image/jpeg,image/png" required><button class="btn-primary">Téléverser</button></form></section>
<section class="table-panel"><div class="panel-heading"><h3>Pièces jointes</h3></div><div class="table-responsive"><table><thead><tr><th>Fichier</th><th>Type</th><th>Taille</th><th>Ajouté par</th></tr></thead><tbody><?php foreach($document['attachments'] as $a):?><tr><td><a href="<?=e(base_url('documents/attachments/'.$a['id'].'/download'))?>"><?=e($a['original_name'])?></a></td><td><?=e($a['mime_type'])?></td><td><?=e(number_format($a['file_size']/1024,1,',',' '))?> Ko</td><td><?=e($a['uploader_name']?:'-')?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="table-panel"><div class="panel-heading"><h3>Historique des statuts</h3></div><div class="table-responsive"><table><thead><tr><th>Date</th><th>Ancien statut</th><th>Nouveau statut</th><th>Acteur</th><th>Motif</th></tr></thead><tbody><?php foreach($document['history'] as $h):?><tr><td><?=e($h['changed_at'])?></td><td><?=e($h['old_status']?:'-')?></td><td><?=e($h['new_status'])?></td><td><?=e($h['actor_name']?:'Système')?></td><td><?=e($h['reason']?:'-')?></td></tr><?php endforeach;?></tbody></table></div></section>
